    descriptions={400:'BAD_REQUEST: malformed JSON or cursor',401:'UNAUTHENTICATED',403:'FORBIDDEN: role mismatch before order lookup',404:'NOT_FOUND: absent or not owned',409:'CONFLICT: state/version conflict, OFFER_CHANGED, PRODUCT_UNAVAILABLE or IDEMPOTENCY_KEY_REUSED',422:'INVALID_INPUT: field/range/duplicate product violation',503:'DEPENDENCY_UNAVAILABLE: no acceptance committed; retry same key on ambiguous outcome'}
